mapper.select:
SELECT * FROM user WHERE 1=1 AND role = #{role} AND status = #{status}
AND (username LIKE CONCAT('%',#{keyword},'%') OR phone LIKE CONCAT('%',#{keyword},'%') OR email LIKE CONCAT('%',#{keyword},'%'))
ORDER BY created_at DESC

